function UIActionDreamlandEntryDialog:__init()
    self.isGotoDreameSpace = false      -- 离开本界面是为了 进入白塔 还是 回到上一次区域界面
    self._dreamlandQuestVos = {}        --所有的关卡
    self._currentSelectedQuestId = 0    -- 选中的 关卡id: 1001 这种
    self._isMajorRewardDrawed = false   -- 当前关卡的 主奖励 是否已经领取了
    self._isPiecesRewardDrawed = false  -- 当前关卡的 碎片奖励 是否已经领取了
end

