function UIActionDreamlandEntryDialog:Awake()
    SetButtonAction(self.ButtonGo, Bind(self, self.OnBtnGo))
end

function UIActionDreamlandEntryDialog:InitData()
    self._dreamlandQuestVos = {}         
    self._dreamlandQuestVos = CfUtils.GetCf(AutoIds.IdSetting3080, "DreamlandQuestVo", true)

    self._currentSelectedQuestId = self._dreamlandQuestVos[1].id

    -- 当从白塔返回本界面时, 需要主动把 MainMenuOversea 场景中的物体关掉, 以节省渲染;
    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)

    CfUtils.FillText( self.TxtTitle1.gameObject, localize("首次通关奖励") )
    CfUtils.FillText( self.TxtTitle2.gameObject, localize("全收集奖励") )
end

function UIActionDreamlandEntryDialog:FillSelf()
    self:RefreshQuestList()
    CfUtils.SetActive(self.UIFX_ActionDreamlandEntryDialog, false)
end

function UIActionDreamlandEntryDialog:RefreshQuestList()
    if not self._isInit then
        self.LoopList:InitGridView(table.count(self._dreamlandQuestVos), Bind(self, self.OnRefreshPlaceIndex))
        self._isInit = true
    else
        GameUtils.ReloadData(self.LoopList, table.count(self._dreamlandQuestVos))
    end

    self:FillQuestInfo()
end


function UIActionDreamlandEntryDialog:OnRefreshPlaceIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local dreamlandQuestVo = self._dreamlandQuestVos[index + 1]
    local scr = CfUtils.GetLuaScr(cell, "Game.UI.FightReady.UIDreamland.ActionDreamlandEntryDialog.UIActionDreamlandEntryNode")
    if scr then
        scr:Refresh(dreamlandQuestVo, index + 1, function()
            self:OnSelectQuest(dreamlandQuestVo)
        end)

        if checkNumber(self._currentSelectedQuestId) == checkNumber(dreamlandQuestVo.id) then
            scr:FillSelect(true)
            scr:PlayAnimation("ActionDreamlandEntryDialogCell_Choose")
        else
            scr:FillSelect(false)
            scr:PlayAnimation("ActionDreamlandEntryDialogCell_Default")
        end
    else 
        printError("koko 左侧关卡选项 没找到 lua 脚本");
    end

    return cell
end


function UIActionDreamlandEntryDialog:OnSelectQuest( dreamlandQuestVo_ )
    if self._currentSelectedQuestId > 0 then
        local ind = self:GetInd(self._currentSelectedQuestId)
        if checkNumber(ind) > 0 then
            local go = self.LoopList:GetShownItemByItemIndex(ind - 1)
            if go then
                local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIDreamland.ActionDreamlandEntryDialog.UIActionDreamlandEntryNode")
                if scr then
                    scr:FillSelect(false)
                    scr:PlayAnimation("ActionDreamlandEntryDialogCell_Cancel")
                end
            end
        end
    end

    self._currentSelectedQuestId = checkNumber(dreamlandQuestVo_.id)
    local ind = self:GetInd(dreamlandQuestVo_.id)
    if checkNumber(ind) > 0 then
        local go = self.LoopList:GetShownItemByItemIndex(ind - 1)
        if go then
            local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIDreamland.ActionDreamlandEntryDialog.UIActionDreamlandEntryNode")
            if scr then
                scr:FillSelect(true)
                scr:PlayAnimation("ActionDreamlandEntryDialogCell_Choose")
            end
        end
    end

    self:FillQuestInfo()
end


function UIActionDreamlandEntryDialog:FillQuestInfo()
    local vo = DreamlandUtils.GetDreamlandQuestVo(self._currentSelectedQuestId)
    if not vo then
        return
    end

    CfUtils.FillText(self.TxtName, vo.levelName)
    CfUtils.FillText(self.TxtState, vo.levelDesc)


    vo = DreamlandUtils.GetDreamlandQuestRewardVo(self._currentSelectedQuestId)

    local homeDojoBoxQuestInfo = DreamlandUtils.GetHomeDojoBoxQuestInfo( self._currentSelectedQuestId ) -- 选中关卡的 dojo, 可能为空, (比如第一次进入白塔时)

    -- local piecesDatasVO = DreamlandUtils.GetAllDreamlandCollectionVoByQuestId( self._currentSelectedQuestId )
    -- local piecesNum = table.count(piecesDatasVO) -- 配表中 碎片数量
    local piecesNum = DreamlandUtils.GetAllPiecesNumByQuestId(self._currentSelectedQuestId) -- 配表中 碎片数量

    self._isMajorRewardDrawed = false 
    self._isPiecesRewardDrawed = false 
    if isNotNull(homeDojoBoxQuestInfo) then
        if homeDojoBoxQuestInfo.isPassed == 1 then
            self._isMajorRewardDrawed = true
        end
        -- 大于等于是为了规避 后端潜在的 错误 (多出一些 "" 元素)
        if isNotNull(homeDojoBoxQuestInfo.piece) and table.count(homeDojoBoxQuestInfo.piece) >= piecesNum then 
            self._isPiecesRewardDrawed = true
        end 
    end

    -- 主线奖励:
    local t = parse_rewards(vo.fristRewards, vo.fristRewardsNum)
    self:FillRewards(self.LayoutGoodNode1, self.GoodNode, t, self._isMajorRewardDrawed )

    -- 碎片奖励:
    t = parse_rewards(vo.collectionReward, vo.collectionRewardNum)
    self:FillRewards(self.LayoutGoodNode2, self.GoodNode1, t, self._isPiecesRewardDrawed )

end


function UIActionDreamlandEntryDialog:FillRewards(parGo, nodeGo, t, isDrawed_ )
    for k, v in pairs(t) do
        -- 每一个奖励
        local go = parGo.transform:Find("go"..k)
        if not go then
            go = CfUtils.InstantiateGo(nodeGo, parGo)
            go.name = "go"..k
        end
        CfUtils.SetActive(go, true)

        -- 绘制 奖励图标

        CfUtils.RefeshGoodGo2(go, v.goodsId, v.goodsNum, nil, nil,             
            function()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)

        local scr = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
        if scr then
            -- 已领取的打勾
            scr:SetSanXingGainShow( isDrawed_ == true )
        end

    end

    if parGo.transform.childCount > table.count(t) then
        for i = table.count(t) + 1, parGo.transform.childCount do 
            local go = parGo.transform:Find("go"..i)
            CfUtils.SetActive(go, false)
        end
    end
end


--进入关卡
function UIActionDreamlandEntryDialog:OnBtnGo()

    printInfo( "===== 进入关卡 ======" )
    self.isGotoDreameSpace = true

    -- todo: 未来要根据不同 关卡, 设置不同的场景;

    UIModule.AddUIPage({ id = Constants.UITypeIds.UIActionDreamlandEntryDialog})

    -- 同步一些 关卡内的 全局信息:
    DreamSpaceStates.questId = self._currentSelectedQuestId
    DreamSpaceStates.isMajorRewardDrawed = self._isMajorRewardDrawed
    DreamSpaceStates.isAllPiecesCollectedAlready = self._isPiecesRewardDrawed

    -- 设置 loading 界面的 bg图:
    local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
    KCookie.Set(Constants.UICacheDataKeys.OP_LOADING_IMG_ID, DreamSpaceStates.LoadingPanel_IMG_ID) 

    -- 梦空间场景的入口
    GameUtils.OpenLoadingPanel(
        UIArgs(Constants.UITypeIds.UIDreamSpaceLvl1SceneEnter, nil),
        {}, Constants.LoadingType.Others, false)

end


function UIActionDreamlandEntryDialog:GetInd(id)
    for k, v in pairs(self._dreamlandQuestVos) do 
        if checkNumber(id) == checkNumber(v.id) then
            return k
        end
    end
    return 0
end


function UIActionDreamlandEntryDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:InitData()
        
        -- 播放 选关页面专属 bgm:
        DreamSpaceSounds.StopAll()
        DreamSpaceSounds.Play( DreamSpaceSounds.music.interface )

        CfUtils.SetUICameraProjection(false)

        local isFinish = false
        DreamlandComponent:OverseaBoxQuestHomeReq(function()
            isFinish = true
        end)
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
        end
    end))
    return coWait
end

function UIActionDreamlandEntryDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        -- 若不是进入白塔, 则要播放 默认bgm
        if self.isGotoDreameSpace == false  then 
            CriWareUtils.PlayRandomBGMFromCDList()
        end 

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionDreamlandEntryDialog
